scoped_changed_extents.text:
    param (
        [Parameter(Mandatory = $true)]
        [string]$GuideContent,

        [Parameter(Mandatory = $true)]
        [string]$RationaleContent
    )

    # One parse supplies both leaf insertion and top-level standalone emission.
    $hashtableSections = @{}
    $listTopSections = New-Object 'System.Collections.Generic.List[hashtable]'
    $hashtableLeaf = $null
    $hashtableTop = $null
    foreach ($strLine in ($RationaleContent -split '\r?\n')) {
        if ($strLine -match '^(#{2,3}) (.+)$') {
            $intLevel = $Matches[1].Length
            $strHeading = $Matches[2]
            $strAnchor = $strHeading.ToLowerInvariant() -replace '[^a-z0-9 -]', '' -replace ' ', '-'
            $strAnchor = $strAnchor -replace '-+', '-' -replace '^-|-$', ''
            $hashtableLeaf = $null
            $hashtableSection = @{
                Heading = ('#' * $intLevel) + ' ' + $strHeading
                Title = $strHeading
                Body = New-Object 'System.Collections.Generic.List[string]'
            }
            if ($intLevel -eq 2) {
                $hashtableTop = $hashtableSection
                $listTopSections.Add($hashtableTop)
                if ($strHeading -eq $script:hashtableLanguage.SummaryHeading) {
                    $hashtableSections[$script:hashtableLanguage.SummaryAnchor] = $hashtableTop
                }
            } else {
                $hashtableLeaf = $hashtableSection
                $hashtableSections[$strAnchor] = $hashtableLeaf
                if ($null -ne $hashtableTop) {
                    $hashtableTop.Body.Add($strLine)
                }
            }
        } else {
            if ($null -ne $hashtableLeaf) {
                $hashtableLeaf.Body.Add($strLine)
            }
            if ($null -ne $hashtableTop) {
                $hashtableTop.Body.Add($strLine)
            }
        }
    }
    foreach ($hashtableSection in @($hashtableSections.Values) + $listTopSections.ToArray()) {
        $hashtableSection.CleanBody = @(ConvertTo-RationaleBody -Lines $hashtableSection.Body.ToArray())
    }
    $listOutputLines = New-Object 'System.Collections.Generic.List[string]'
    $intSummaryScanIndex = 0
    $boolSummaryTextSeen = $false
    $boolSummaryHeadingSeen = $false
    foreach ($strLine in ($GuideContent -split '\r?\n')) {
        if ($strLine.Trim() -eq '*This section intentionally left blank.*') {
            continue
        }
        if ($strLine -match '^\s*<!--\s*rationale-toc:\s*(.+?)\s*-->\s*$') {
            $listOutputLines.Add($Matches[1].Trim())
            continue
        }
        if ($strLine -match '^\s*<!--\s*(rationale-anchor|RATIONALE):\s*(.+?)\s*-->\s*$') {
            $boolIncludeHeading = $Matches[1] -eq 'rationale-anchor'
            $strAnchor = $Matches[2].Trim()
            if (-not $hashtableSections.ContainsKey($strAnchor) -or
                $hashtableSections[$strAnchor].CleanBody.Count -eq 0) {
                throw 'missing-rationale-anchor'
            }
            if ($boolIncludeHeading) {
                $listOutputLines.Add('')
                $listOutputLines.Add($hashtableSections[$strAnchor].Heading)
                $listOutputLines.Add('')
            }
            foreach ($strBodyLine in $hashtableSections[$strAnchor].CleanBody) {
                $listOutputLines.Add($strBodyLine)
            }
            continue
        }
        if ($script:hashtableLanguage.SummaryBefore -ne '' -and
            $hashtableSections.ContainsKey($script:hashtableLanguage.SummaryAnchor)) {
            $strSummaryHeading = $script:hashtableLanguage.SummaryHeading
            $strSummaryAnchor = $script:hashtableLanguage.SummaryAnchor
            $boolSummaryTocBoundary = $strLine -match ('^- \[' + [regex]::Escape($script:hashtableLanguage.SummaryBefore) + '\]')
            $boolSummarySectionBoundary = $strLine -match ('^## ' + [regex]::Escape($script:hashtableLanguage.SummaryBefore))
            if ($boolSummaryTocBoundary -or $boolSummarySectionBoundary) {
                # Include guide, marker and rationale output already emitted.
                # Each line is inspected once, even with repeated boundaries.
                while ($intSummaryScanIndex -lt $listOutputLines.Count) {
                    $strObservedLine = $listOutputLines[$intSummaryScanIndex]
                    if ($strObservedLine -match [regex]::Escape($strSummaryHeading)) {
                        $boolSummaryTextSeen = $true
                    }
                    if ($strObservedLine -match ('^## ' + [regex]::Escape($strSummaryHeading))) {
                        $boolSummaryHeadingSeen = $true
                    }
                    $intSummaryScanIndex++
                }
            }
            if ($boolSummaryTocBoundary -and -not $boolSummaryTextSeen) {
                $listOutputLines.Add(('- [{0}](#{1})' -f $strSummaryHeading, $strSummaryAnchor))
                $boolSummaryTextSeen = $true
            }
            if ($boolSummarySectionBoundary -and -not $boolSummaryHeadingSeen) {
                while ($listOutputLines.Count -gt 0 -and
                    $listOutputLines[$listOutputLines.Count - 1].Trim() -in @('', '---')) {
                    $listOutputLines.RemoveAt($listOutputLines.Count - 1)
                }
                $intSummaryScanIndex = [Math]::Min($intSummaryScanIndex, $listOutputLines.Count)
                $listOutputLines.Add('')
                $listOutputLines.Add('## ' + $strSummaryHeading)
                $boolSummaryTextSeen = $true
                $boolSummaryHeadingSeen = $true
                $listOutputLines.Add('')
                foreach ($strBodyLine in $hashtableSections[$strSummaryAnchor].CleanBody) {
                    $listOutputLines.Add($strBodyLine)
                }
                $listOutputLines.Add('')
                $listOutputLines.Add('---')
                $listOutputLines.Add('')
            }
        }
        $listOutputLines.Add($strLine)
        if ($script:hashtableLanguage.Composition -eq 'HeadingLinked' -and $strLine -match '^(#{2,3}) (.+)$') {
            $strHeading = $Matches[2]
            $strAnchor = $strHeading.ToLowerInvariant() -replace '[^a-z0-9 -]', '' -replace ' ', '-'
            $strAnchor = $strAnchor -replace '-+', '-' -replace '^-|-$', ''
            if ($hashtableSections.ContainsKey($strAnchor) -and $hashtableSections[$strAnchor].CleanBody.Count -gt 0) {
                $listOutputLines.Add('')
                foreach ($strBodyLine in $hashtableSections[$strAnchor].CleanBody) {
                    $listOutputLines.Add($strBodyLine)
                }
            }
        }
    }
    if ($script:hashtableLanguage.AppendStandalone) {
        $arrExistingHeadings = @($listOutputLines | Where-Object { $_ -match '^## ' } |
            ForEach-Object { ($_ -replace '^## ', '').Trim() })
        foreach ($hashtableSection in $listTopSections) {
            if ($hashtableSection.Title -eq 'Table of Contents' -or
                $hashtableSection.Title -match '^Executive Summary|Rationale$' -or
                $arrExistingHeadings -contains $hashtableSection.Title) {
                continue
            }
            $listOutputLines.Add('')
            $listOutputLines.Add($hashtableSection.Heading)
            if ($hashtableSection.CleanBody.Count -gt 0) {
                $listOutputLines.Add('')
                foreach ($strBodyLine in $hashtableSection.CleanBody) {
                    $listOutputLines.Add($strBodyLine)
                }
            }
        }
    }
    $strOutput = $listOutputLines.ToArray() -join "`n"
    while ($strOutput -match "`n`n`n") {
        $strOutput = $strOutput -replace "`n`n`n", "`n`n"
    }
    return $strOutput.TrimEnd("`n") + "`n"
}

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
if (Test-Path Variable:PSNativeCommandUseErrorActionPreference) {
    $PSNativeCommandUseErrorActionPreference = $false
}
$strPowerShell = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
$boolWindows = [Environment]::OSVersion.Platform -eq [PlatformID]::Win32NT
if (($ExpectedHost -eq 'WindowsPowerShell51' -and
        (-not $boolWindows -or $PSVersionTable.PSEdition -cne 'Desktop' -or $PSVersionTable.PSVersion.Major -ne 5)) -or
    ($ExpectedHost -eq 'WindowsPowerShell7' -and (-not $boolWindows -or $PSVersionTable.PSVersion.Major -ne 7)) -or
    ($ExpectedHost -eq 'LinuxPowerShell7' -and ($boolWindows -or $PSVersionTable.PSVersion.Major -ne 7))) {
    throw 'generator-test: wrong platform or PowerShell edition'
}
$strGit = (Microsoft.PowerShell.Core\Get-Command -Name git -CommandType Application -All -TotalCount 1 -ErrorAction Stop).Source
$strRepository = Split-Path -Path (Split-Path -Path $PSScriptRoot -Parent) -Parent
$strRepository = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($strRepository)
$strScratchParent = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath([IO.Path]::GetTempPath())
$strScratch = Join-Path -Path $strScratchParent -ChildPath ('styleguide-generator-' + [Guid]::NewGuid().ToString('N'))
[void][IO.Directory]::CreateDirectory($strScratch)
$objEncoding = New-Object System.Text.UTF8Encoding($false, $true)
$strGeneratorPath = Join-Path -Path $PSScriptRoot -ChildPath 'Generate-StyleGuideArtifacts.ps1'
$strGenerator = [IO.File]::ReadAllText($strGeneratorPath, $objEncoding)
$strStorage = 'not-required'
if ($ExpectedHost -eq 'LinuxPowerShell7') {
    foreach ($strStoragePath in @($strRepository, $strScratch)) {
        $arrStorage = @(& /usr/bin/findmnt --noheadings --output FSTYPE --target $strStoragePath)
        if ($LASTEXITCODE -ne 0 -or $arrStorage.Count -ne 1 -or $arrStorage[0].Trim() -cne 'ext4') {
            throw 'generator-test: native ext4 is required for source and fixture storage'
        }
    }
    $strStorage = 'ext4'
}

} catch {
    $boolPrimaryFailure = $true
    throw
} finally {
    $strCleanupFailure = $null
    try {
        # Only this invocation's independently named child may be removed.
        $strResolvedScratch = [IO.Path]::GetFullPath($strScratch)
        if ([IO.Path]::GetDirectoryName($strResolvedScratch).TrimEnd('\', '/') -cne $strScratchParent.TrimEnd('\', '/') -or
            [IO.Path]::GetFileName($strResolvedScratch) -cnotmatch '^styleguide-generator-[0-9a-f]{32}$') {
            $strCleanupFailure = 'generator-test: cleanup containment failure'
        } else {
            Remove-Item -LiteralPath $strResolvedScratch -Recurse -Force
        }
    } catch {
        # Classify cleanup without exposing its details or replacing the primary error.
        $strCleanupFailure = 'generator-test: cleanup failed'
    }
    if ($null -ne $strCleanupFailure) {
        if ($boolPrimaryFailure) {
            Write-Warning -Message $strCleanupFailure -WarningAction Continue
        } else {
            throw $strCleanupFailure
        }
    }
}
'Generator tests passed: {0} assertions; edition={1}; version={2}; executable={3}; storage={4}; image={5}/{6}.' -f
    $script:intAssertions, $PSVersionTable.PSEdition, $PSVersionTable.PSVersion, $strPowerShell, $strStorage,
    $env:ImageOS, $env:ImageVersion

const generatorPlatforms = ["generator_windows_51", "generator_windows_7", "generator_linux_7"];
// The policy owns this finite list; workflow and test expectations stay independent.
const generatorRequiredStatement = "$arrRequired = @(" + generatorPlatforms.map(id => "'" + id + "'").join(', ') + ')';
const generatorAdmission = "$ErrorActionPreference = 'Stop'\n$objResults = $env:GENERATOR_RESULTS | ConvertFrom-Json -ErrorAction Stop\n" + generatorRequiredStatement + "\nif (@($objResults.PSObject.Properties).Count -ne $arrRequired.Count) {\n    throw 'Generator platform results are incomplete.'\n}\nforeach ($strJob in $arrRequired) {\n    $objProperty = $objResults.PSObject.Properties[$strJob]\n    if ($null -eq $objProperty -or $objProperty.Value.result -cne 'success' -or\n        $objProperty.Value.outputs.revision -cne $env:GITHUB_SHA -or\n        $env:GITHUB_SHA -cnotmatch '^[0-9a-f]{40}$') {\n        throw 'Generator platform admission failed.'\n    }\n}\n";

function validateRunStep(step, id, expected) {
  const keys = ['id', 'shell', 'run'];
  if (Object.hasOwn(step, 'name')) keys.push('name');
  expectExactKeys(step, keys, 'code-step-shape');
  if (step.id !== id || step.shell !== 'pwsh' || (step.name !== undefined && typeof step.name !== 'string')) fail('code-step-interface');
  const lines = visibleLines(step.run);
  if (id === 'acquire') {
    // This bootstrap necessarily runs before repo helpers exist. Source safety is
    // covered by accepted-loader behavior tests and maintenance review; this is
    // deliberately not a shell interpreter or a source-spelling proof.
    if (lines.length === 0) fail('acquisition-empty');
    return;
  }
  if (id === 'validate') {
    if (lines.length !== 2) fail('helper-call');
    expectDeepEqual(helperCall(lines[0].replace(/;$/u, '')), ['node', './.github/workflows/Validate-WorkflowPolicy.mjs', '.github/workflows/build.yml', '.github/workflows/markdownlint.yml'], 'helper-call');
    if (!/^if\s*\(\s*\$LASTEXITCODE\s+-ne\s+0\s*\)\s*\{\s*throw\s+(['"])Workflow policy validation failed\.\1\s*;?\s*\}$/u.test(lines[1])) fail('native-failure-check');
    return;
  }
  if (id === 'audit') {
    if (lines.length !== 2) fail('helper-call');
    expectDeepEqual(helperCall(lines[0].replace(/;$/u, '')), ['node', './.github/workflows/Check-NpmAudit.mjs', '--ci'], 'helper-call');
    if (!/^if\s*\(\s*\$LASTEXITCODE\s+-ne\s+0\s*\)\s*\{\s*throw\s+(['"])[A-Za-z0-9 .:-]+\1\s*;?\s*\}$/u.test(lines[1])) fail('native-failure-check');
    return;
  }
  if (lines.length !== 1) fail('helper-call');
  expectDeepEqual(helperCall(lines[0]), expected, 'helper-call');
}

function validateWorkflowObject(fileName, workflow, contract) {
  if (!WORKFLOWS.includes(fileName)) fail('workflow-name');
  expectExactKeys(workflow, ['name', 'on', 'permissions', 'jobs'], 'workflow-shape');
  if (typeof workflow.name !== 'string' || !workflow.name.trim()) fail('workflow-name');
  const build = fileName === 'build.yml';
  const events = { push: null, pull_request: null };
  if (!build) {
    const schedule = workflow.on?.schedule;
    if (!Array.isArray(schedule) || schedule.length !== 1) fail('workflow-events');
    expectExactKeys(schedule[0], ['cron'], 'workflow-events');
    const weekly = typeof schedule[0].cron === 'string' && /^(\d{1,2}) +(\d{1,2}) +\* +\* +([0-6])$/u.exec(schedule[0].cron);
    if (!weekly || Number(weekly[1]) > 59 || Number(weekly[2]) > 23) fail('workflow-events');
    events.schedule = schedule;
  }
  expectDeepEqual(workflow.on, events, 'workflow-events');
  expectDeepEqual(workflow.permissions, {}, 'workflow-permissions');
  const codeJobs = build ? [contract.roles.artifactVerifier, ...generatorPlatforms] : ['policy', 'markdownlint'];
  expectExactKeys(workflow.jobs, build ? [...codeJobs, 'publish_committed_artifacts'] : codeJobs, 'isolation-jobs');
  for (const id of codeJobs) {
    const job = workflow.jobs[id];
    const platform = generatorPlatforms.indexOf(id);
    const aggregate = build && platform < 0;
    const keys = ['if', 'runs-on', 'timeout-minutes', 'permissions', 'steps'];
    if (aggregate) keys.push('needs');
    if (platform >= 0) keys.push('outputs');
    expectExactKeys(job, keys, 'code-job-shape');
    const live = "github.event_name != 'push' || github.event.deleted != true";
    if (job.if !== (aggregate ? 'always() && (' + live + ')' : live)) fail('code-job-event');
    expectDeepEqual(job.permissions, {}, 'code-job-permissions');
    const runner = platform === 0 || platform === 1 ? 'windows-2025' : 'ubuntu-24.04';
    if (job['runs-on'] !== runner || job['timeout-minutes'] !== 30) fail('code-job-execution');
    if (aggregate) expectDeepEqual(job.needs, generatorPlatforms, 'generator-dependencies');
    if (platform >= 0) {
      expectDeepEqual(job.outputs, { revision: '${{ steps.proof.outputs.revision }}' }, 'generator-outputs');
      const shell = platform === 0 ? 'powershell' : 'pwsh';
      const expectedCount = platform === 2 ? 3 : 2;
      if (!Array.isArray(job.steps) || job.steps.length !== expectedCount) fail('code-step-cardinality');
      const acquire = job.steps[0];
      expectExactKeys(acquire, ['id', 'shell', 'run', ...(Object.hasOwn(acquire, 'name') ? ['name'] : [])], 'code-step-shape');
      if (acquire.id !== 'acquire' || acquire.shell !== shell || visibleLines(acquire.run).length === 0) fail('code-step-interface');
      if (platform === 2) validateRunStep(job.steps[1], 'verify-checkout-credentials', ['./.github/workflows/Test-CheckoutCredentials.ps1']);
      const proof = job.steps.at(-1);
      expectExactKeys(proof, ['id', 'shell', 'run', ...(Object.hasOwn(proof, 'name') ? ['name'] : [])], 'code-step-shape');
      if (proof.id !== 'proof' || proof.shell !== shell) fail('code-step-interface');
      const host = ['WindowsPowerShell51', 'WindowsPowerShell7', 'LinuxPowerShell7'][platform];
      const lines = visibleLines(proof.run);
      if (lines.length !== 23) fail('generator-proof');
      const expected = [
        "$env:GIT_CONFIG_NOSYSTEM = '1'",
        "$env:GIT_CONFIG_GLOBAL = '" + (platform === 2 ? '/dev/null' : 'NUL') + "'",
        "$env:GIT_TERMINAL_PROMPT = '0'",
        "$env:GIT_NO_REPLACE_OBJECTS = '1'",
        '$strPowerShellPath = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName',
        'if ([string]::IsNullOrEmpty($strPowerShellPath) -or -not [IO.File]::Exists($strPowerShellPath)) {',
        "throw 'The current PowerShell executable is unavailable.'",
        '}',
      ];
      for (const pass of [1, 2]) expected.push(
        "& $strPowerShellPath -NoLogo -NoProfile -NonInteractive -File './.github/workflows/Test-StyleGuideGenerator.ps1' -ExpectedHost " + host,
        '$intGeneratorExit = $LASTEXITCODE',
        'if ($intGeneratorExit -isnot [int] -or $intGeneratorExit -ne 0) {',
        "throw 'Generator pass " + pass + " failed.'",
        '}',
      );
      expectDeepEqual(lines.slice(0, 18), expected, 'generator-proof');
      const git = platform === 2 ? "'/usr/bin/git'" : "'C:\\Program Files\\Git\\bin\\git.exe'";
      const tail = [
        "$arrHead = @(& " + git + " rev-parse --verify 'HEAD^{commit}')",
        "if ($LASTEXITCODE -ne 0 -or $arrHead.Count -ne 1 -or $arrHead[0] -cne $env:GITHUB_SHA) {",
        "throw 'Generator proof revision mismatch.';",
        '}',
        '[IO.File]::AppendAllText($env:GITHUB_OUTPUT, (\'revision=\' + $arrHead[0] + "`n"), (New-Object Text.UTF8Encoding($false)))',
      ];
      expectDeepEqual(lines.slice(18).map(line => line.replace(/;$/u, '')), tail.map(line => line.replace(/;$/u, '')), 'generator-proof');
      continue;
    }
    const roles = [
      ...(aggregate ? [['admit-generator-platforms', null]] : []),
      ['acquire', null],
      ['verify-checkout-credentials', ['./.github/workflows/Test-CheckoutCredentials.ps1']],
      ...(build ? [] : [['initialize-toolchain', ['./.github/workflows/Initialize-CiToolchain.ps1', '-WorkflowDependencies']]]),
      build ? ['generate_style_guide_artifacts', ['./.github/workflows/Test-StyleGuideArtifacts.ps1']]
        : id === 'policy' ? ['validate', null] : ['lint', ['./.github/workflows/Invoke-MarkdownLint.ps1']],
      ...(id === 'markdownlint' ? [['audit', null]] : []),
    ];
    if (!Array.isArray(job.steps) || job.steps.length !== roles.length) fail('code-step-cardinality');
    roles.forEach(([role, call], index) => {
      const step = job.steps[index];
      if (role === 'admit-generator-platforms') {
        expectExactKeys(step, ['id', 'shell', 'run', 'env', ...(Object.hasOwn(step, 'name') ? ['name'] : [])], 'generator-admission');
        if (step.id !== role || step.shell !== 'pwsh') fail('generator-admission');
        expectDeepEqual(step.env, { GENERATOR_RESULTS: '${{ toJSON(needs) }}' }, 'generator-admission');
        expectDeepEqual(visibleLines(step.run), visibleLines(generatorAdmission), 'generator-admission');
      } else validateRunStep(step, role, call);
    });
  }
  if (!build) return;
  const publisher = workflow.jobs.publish_committed_artifacts;
  expectExactKeys(publisher, ['runs-on', 'timeout-minutes', 'permissions', 'needs', 'steps'], 'publisher-shape');
  expectDeepEqual(publisher.permissions, { contents: 'read' }, 'publisher-permissions');
  if (publisher.needs !== contract.roles.artifactVerifier || publisher['runs-on'] !== 'ubuntu-24.04' || publisher['timeout-minutes'] !== 10) fail('publisher-execution');
  if (!Array.isArray(publisher.steps) || publisher.steps.length !== 2) fail('publisher-steps');
  for (const [index, actionName] of ['checkout', 'uploadArtifact'].entries()) {
    const step = publisher.steps[index];
    const keys = ['id', 'uses', 'with'];
    if (Object.hasOwn(step, 'name')) keys.push('name');
    expectExactKeys(step, keys, 'publisher-step-shape');
    if (step.id !== (index === 0 ? 'checkout_repository' : 'publish_committed_style_guide_artifacts') || step.uses !== contract.actions[actionName].uses) fail('action-identity');
    expectDeepEqual(step.with, contract.actions[actionName].inputs, 'action-inputs');
  }
}

generator_linux_7:
  if: github.event_name != 'push' || github.event.deleted != true
  runs-on: ubuntu-24.04
  timeout-minutes: 30
  permissions: {}
  outputs:
    revision: ${{ steps.proof.outputs.revision }}
  steps:
    - name: Acquire the exact revision without credentials
      id: acquire
      shell: pwsh
      run: |
        $ErrorActionPreference = 'Stop'
        $PSNativeCommandUseErrorActionPreference = $false
        if ($env:GITHUB_SERVER_URL -cne 'https://github.com' -or
            $env:GITHUB_REPOSITORY -cne 'franklesniak/PSStyleGuide') {
            throw 'Unexpected acquisition repository.'
        }
        foreach ($strName in @('GITHUB_TOKEN', 'GH_TOKEN', 'ACTIONS_RUNTIME_TOKEN',
            'GIT_CONFIG_COUNT', 'GIT_CONFIG_PARAMETERS', 'GIT_DIR', 'GIT_WORK_TREE',
            'GIT_INDEX_FILE', 'GIT_OBJECT_DIRECTORY', 'GIT_ALTERNATE_OBJECT_DIRECTORIES')) {
            if ([Environment]::GetEnvironmentVariable($strName)) {
                throw 'Unexpected credentials or external Git configuration.'
            }
        }
        $env:GIT_CONFIG_NOSYSTEM = '1'
        $env:GIT_CONFIG_GLOBAL = '/dev/null'
        $env:GIT_TERMINAL_PROMPT = '0'
        $env:GIT_NO_REPLACE_OBJECTS = '1'
        $strRevision = $env:GITHUB_SHA
        if ($strRevision -cnotmatch '^[0-9a-f]{40}$') { throw 'A full commit hash is required.' }
        if (@([IO.Directory]::EnumerateFileSystemEntries($PWD.Path)).Count -ne 0) {
            throw 'The acquisition workspace must be empty.'
        }
        & /usr/bin/git -c core.hooksPath=/dev/null init --quiet .
        if ($LASTEXITCODE -ne 0) { throw 'git init failed.' }
        & /usr/bin/git config --local core.autocrlf false
        if ($LASTEXITCODE -ne 0) { throw 'Git byte-preserving checkout configuration failed.' }
        & /usr/bin/git remote add origin 'https://github.com/franklesniak/PSStyleGuide'
        if ($LASTEXITCODE -ne 0) { throw 'git remote add failed.' }
        for ($intAttempt = 1; $intAttempt -le 3; $intAttempt++) {
            & /usr/bin/git -c credential.helper= -c http.extraheader= -c core.hooksPath=/dev/null fetch --depth 1 --no-tags --no-recurse-submodules origin $strRevision
            if ($LASTEXITCODE -eq 0) { break }
            if ($intAttempt -eq 3) { throw 'Exact revision fetch failed after three attempts.' }
            Start-Sleep -Seconds 2
        }
        $strFetched = & /usr/bin/git rev-parse --verify 'FETCH_HEAD^{commit}'
        if ($LASTEXITCODE -ne 0 -or $strFetched -cne $strRevision) { throw 'Fetched commit mismatch.' }
        & /usr/bin/git -c core.hooksPath=/dev/null checkout --quiet --detach $strRevision
        if ($LASTEXITCODE -ne 0) { throw 'Exact checkout failed.' }
        $strHead = & /usr/bin/git rev-parse --verify 'HEAD^{commit}'
        if ($LASTEXITCODE -ne 0 -or $strHead -cne $strRevision) { throw 'Checked-out commit mismatch.' }
    - name: Verify checkout credentials
      id: verify-checkout-credentials
      shell: pwsh
      run: |
        ./.github/workflows/Test-CheckoutCredentials.ps1
    - name: Run the actual generator suite twice
      id: proof
      shell: pwsh
      run: |
        $env:GIT_CONFIG_NOSYSTEM = '1'
        $env:GIT_CONFIG_GLOBAL = '/dev/null'
        $env:GIT_TERMINAL_PROMPT = '0'
        $env:GIT_NO_REPLACE_OBJECTS = '1'
        $strPowerShellPath = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
        if ([string]::IsNullOrEmpty($strPowerShellPath) -or -not [IO.File]::Exists($strPowerShellPath)) {
            throw 'The current PowerShell executable is unavailable.'
        }
        & $strPowerShellPath -NoLogo -NoProfile -NonInteractive -File './.github/workflows/Test-StyleGuideGenerator.ps1' -ExpectedHost LinuxPowerShell7
        $intGeneratorExit = $LASTEXITCODE
        if ($intGeneratorExit -isnot [int] -or $intGeneratorExit -ne 0) {
            throw 'Generator pass 1 failed.'
        }
