        $objResults = $env:GENERATOR_RESULTS | ConvertFrom-Json -ErrorAction Stop
        $arrRequired = @('generator_windows_51', 'generator_windows_7', 'generator_linux_7')
        if (@($objResults.PSObject.Properties).Count -ne $arrRequired.Count) {
            throw 'Generator platform results are incomplete.'
        }
        foreach ($strJob in $arrRequired) {
            $objProperty = $objResults.PSObject.Properties[$strJob]
            if ($null -eq $objProperty -or $objProperty.Value.result -cne 'success' -or
                $objProperty.Value.outputs.revision -cne $env:GITHUB_SHA -or
                $env:GITHUB_SHA -cnotmatch '^[0-9a-f]{40}$') {
                throw 'Generator platform admission failed.'
            }
        }
    - name: Acquire the exact revision without credentials
      id: acquire
      shell: pwsh
      run: |
        $ErrorActionPreference = 'Stop'
        $PSNativeCommandUseErrorActionPreference = $false
        if ($env:GITHUB_SERVER_URL -cne 'https://github.com' -or
            $env:GITHUB_REPOSITORY -cne 'franklesniak/PSStyleGuide') {
            throw 'Unexpected acquisition repository.'
        }
        foreach ($strName in @('GITHUB_TOKEN', 'GH_TOKEN', 'ACTIONS_RUNTIME_TOKEN',
            'GIT_CONFIG_COUNT', 'GIT_CONFIG_PARAMETERS', 'GIT_DIR', 'GIT_WORK_TREE',
            'GIT_INDEX_FILE', 'GIT_OBJECT_DIRECTORY', 'GIT_ALTERNATE_OBJECT_DIRECTORIES')) {
            if ([Environment]::GetEnvironmentVariable($strName)) {
                throw 'Unexpected credentials or external Git configuration.'
            }
        }
        $env:GIT_CONFIG_NOSYSTEM = '1'
        $env:GIT_CONFIG_GLOBAL = '/dev/null'
        $env:GIT_TERMINAL_PROMPT = '0'
        $env:GIT_NO_REPLACE_OBJECTS = '1'
        $strRevision = $env:GITHUB_SHA
        if ($strRevision -cnotmatch '^[0-9a-f]{40}$') { throw 'A full commit hash is required.' }
        if (@([IO.Directory]::EnumerateFileSystemEntries($PWD.Path)).Count -ne 0) {
            throw 'The acquisition workspace must be empty.'
        }
        & /usr/bin/git -c core.hooksPath=/dev/null init --quiet .
        if ($LASTEXITCODE -ne 0) { throw 'git init failed.' }
        & /usr/bin/git config --local core.autocrlf false
        if ($LASTEXITCODE -ne 0) { throw 'Git byte-preserving checkout configuration failed.' }
        & /usr/bin/git remote add origin 'https://github.com/franklesniak/PSStyleGuide'
        if ($LASTEXITCODE -ne 0) { throw 'git remote add failed.' }
        for ($intAttempt = 1; $intAttempt -le 3; $intAttempt++) {
            & /usr/bin/git -c credential.helper= -c http.extraheader= -c core.hooksPath=/dev/null fetch --depth 1 --no-tags --no-recurse-submodules origin $strRevision
            if ($LASTEXITCODE -eq 0) { break }
            if ($intAttempt -eq 3) { throw 'Exact revision fetch failed after three attempts.' }
            Start-Sleep -Seconds 2
        }
        $strFetched = & /usr/bin/git rev-parse --verify 'FETCH_HEAD^{commit}'
        if ($LASTEXITCODE -ne 0 -or $strFetched -cne $strRevision) { throw 'Fetched commit mismatch.' }
        & /usr/bin/git -c core.hooksPath=/dev/null checkout --quiet --detach $strRevision
        if ($LASTEXITCODE -ne 0) { throw 'Exact checkout failed.' }
        $strHead = & /usr/bin/git rev-parse --verify 'HEAD^{commit}'
        if ($LASTEXITCODE -ne 0 -or $strHead -cne $strRevision) { throw 'Checked-out commit mismatch.' }
    - name: Verify checkout credentials
      id: verify-checkout-credentials
